def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 100:
        return 'C'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    opp_c = opp.count('C')
    my_c = me.count('C')

    def opp_rate(seq):
        if not seq:
            return 0.5
        return seq.count('C') / len(seq)

    recent_len = min(8, n)
    recent_opp = opp[-recent_len:]
    recent_my = me[-recent_len:]
    recent_opp_rate = opp_rate(recent_opp)

    # Defection / cooperation streaks by opponent
    def_streak = 0
    for a in reversed(opp):
        if a == 'D':
            def_streak += 1
        else:
            break

    coop_streak = 0
    for a in reversed(opp):
        if a == 'C':
            coop_streak += 1
        else:
            break

    # My own defection streak
    my_def_streak = 0
    for a in reversed(me):
        if a == 'D':
            my_def_streak += 1
        else:
            break

    last_my = me[-1]
    last_opp = opp[-1]
    remaining = 100 - n

    overall_opp_rate = opp_c / n

    # ---- Endgame ----
    # Last two rounds: grab DC payoff if opponent likely to cooperate, else DD.
    if remaining <= 2:
        if last_opp == 'C' and recent_opp_rate >= 0.4:
            return 'D'
        if last_opp == 'D':
            return 'D'
        return 'C'

    # Last handful of rounds: exploit known cooperators, punish known defectors.
    if remaining <= 6:
        if overall_opp_rate >= 0.7:
            return 'D'
        if overall_opp_rate <= 0.3:
            return 'D'
        if last_opp == 'C':
            return 'D'
        return 'D'

    # ---- Opening ----
    if n == 1:
        if last_opp == 'D':
            return 'D'
        return 'C'

    # ---- Heavily exploitative opponent: defect, rare forgives ----
    if overall_opp_rate <= 0.2:
        if def_streak >= 4:
            return 'D'
        if rng.random() < 0.1:
            return 'C'
        return 'D'

    # ---- Strong exploitative push: if opponent almost always defected recently ----
    if recent_opp_rate <= 0.15 and def_streak >= 2:
        return 'D'

    # ---- Opponent nearly always cooperates: cooperate, rarely probe late ----
    if opp_c >= n - 1:
        # Only probe if very late and a DC gain is meaningful
        if remaining <= 15 and remaining > 6 and rng.random() < 0.25:
            return 'D'
        return 'C'

    # ---- If we're stuck in mutual defection, try to break out ----
    if def_streak >= 3 and my_def_streak >= 3:
        if rng.random() < 0.15:
            return 'C'
        return 'D'

    # ---- Long opponent cooperation streak: mostly cooperate, rare probe ----
    if coop_streak >= 6 and remaining > 15:
        if rng.random() < 0.06:
            return 'D'
        return 'C'

    # ---- Standard tit-for-tat-like response ----
    if last_opp == 'D':
        # Isolated defection after a cooperative run: forgive once.
        if n >= 3 and opp[-2] == 'C' and opp[-3] == 'C' and recent_opp_rate >= 0.5:
            if rng.random() < 0.7:
                return 'C'
            return 'D'
        # Long defection streak: defect, occasional forgiveness to escape DD.
        if def_streak >= 3:
            if rng.random() < 0.12:
                return 'C'
            return 'D'
        if def_streak >= 2:
            if rng.random() < 0.08:
                return 'C'
            return 'D'
        # Single defection: retaliate once.
        if rng.random() < 0.85:
            return 'D'
        return 'C'

    # Opponent cooperated last round.
    # If we've been defecting a lot but they still cooperated, return to C.
    if my_def_streak >= 2 and last_opp == 'C':
        return 'C'

    # Very cooperative overall & recent: keep cooperating, occasional probe.
    if overall_opp_rate >= 0.8 and recent_opp_rate >= 0.75:
        if remaining <= 25 and rng.random() < 0.08:
            return 'D'
        return 'C'

    # Moderately cooperative: cooperate.
    if recent_opp_rate >= 0.5:
        return 'C'

    # Moderately exploitative: mixed punishment.
    if recent_opp_rate < 0.35:
        if def_streak >= 1:
            if rng.random() < 0.7:
                return 'D'
            return 'C'
        return 'D'

    return 'C'
